    "body": "<svg width=\"519\" height=\"567\" viewBox=\"0 0 519 567\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n<path d=\"M0 425.377C0 446.877 47.6667 479.044 71.5 497.377V160.377H184C225 160.377 259 217.883 194.5 248.877L92 299.377V358.877C152.5 421.71 275.8 549.377 285 557.377C300.532 570.883 324 567.978 341 557.377C388.5 532.383 479.9 470.377 493.5 460.377C507.1 450.377 519 432.383 519 410.377V267.377C519 258.977 512.333 256.877 509 256.877H400C362 256.877 350.5 267.377 277 329.377H445.5V395.877C445.5 401.077 443 406.323 437 410.377C406.167 431.21 343.3 473.677 338.5 476.877C332 481.21 324.5 484.383 317 476.877L180 333.377C392 259.263 295 86.377 181 86.377C149.5 86.3829 75.2 86.377 72 86.377C58.2216 86.3769 0 114.377 0 130.377V425.377Z\" fill=\"#062A4C\"/>\n<path d=\"M226.5 6.38119L120 58.8812C203 58.8812 230.378 58.8812 291 93.8814L519 221.881V145.881C519 136.681 517.5 118.242 491.5 105.381C429.5 74.7147 302.6 11.9812 291 6.38119C279.4 0.78119 245.552 -4.6172 226.5 6.38119Z\" fill=\"#017E8A\"/>\n</svg>\n"
